export function getExamPrepPaper(unitId: string, variant: number): GeneratedPaper | undefined {
  return EXAM_PREP_PAPERS[unitId]?.[variant] ?? EXAM_PREP_PAPERS_OLD_PHARM[unitId]?.[variant];
}
